import java.util.*;

class Solution {
  public int numDistinctIslands2(int[][] grid) {
    Set<String> shapes = new HashSet<>();
    for (int i = 0; i < grid.length; i++)
      for (int j = 0; j < grid[0].length; j++)
        if (grid[i][j] == 1) {
          List<int[]> cells = new ArrayList<>();
          collect(grid, i, j, cells);
          shapes.add(canonical(cells));
        }
    return shapes.size();
  }

  private void collect(int[][] g, int i, int j, List<int[]> cells) {
    if (i < 0 || j < 0 || i >= g.length || j >= g[0].length || g[i][j] != 1) return;
    g[i][j] = 0;
    cells.add(new int[] {i, j});
    collect(g, i + 1, j, cells);
    collect(g, i - 1, j, cells);
    collect(g, i, j + 1, cells);
    collect(g, i, j - 1, cells);
  }

  // smallest encoding over the 8 rotations / reflections, each shifted to start at the origin
  private String canonical(List<int[]> cells) {
    String best = null;
    int[][] signs = {{1, 1}, {1, -1}, {-1, 1}, {-1, -1}};
    for (int swap = 0; swap < 2; swap++)
      for (int[] s : signs) {
        List<long[]> pts = new ArrayList<>();
        for (int[] c : cells) {
          long x = swap == 0 ? c[0] : c[1], y = swap == 0 ? c[1] : c[0];
          pts.add(new long[] {x * s[0], y * s[1]});
        }
        pts.sort((a, b) -> a[0] != b[0] ? Long.compare(a[0], b[0]) : Long.compare(a[1], b[1]));
        StringBuilder sb = new StringBuilder();
        for (long[] p : pts) sb.append(p[0] - pts.get(0)[0]).append(':').append(p[1] - pts.get(0)[1]).append(',');
        String enc = sb.toString();
        if (best == null || enc.compareTo(best) < 0) best = enc;
      }
    return best;
  }
}
